for (const item of $input.all()) {
  try {
    // Парсим строку в объект
    const parsed = JSON.parse(item.json.message);

    // Записываем распарсенные данные в json
    item.json.parsed = parsed;

    // Можно сразу вытащить нужные поля
    item.json.chat_id = parsed.chat_id;
    item.json.text = parsed.message;
    item.json.type = parsed.type;
  } catch (error) {
    item.json.error = 'Invalid JSON';
  }
}

return $input.all();

const items = $input.all();
const user = $('Получить данные пользователя').item.json;

function fmtDate(v) {
  if (v === null || v === undefined || v === '') return '—';
  let raw = v;
  if (typeof v === 'string' && /^\d+$/.test(v.trim())) {
    raw = Number(v.trim());
  }
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return String(v);
  return d.toLocaleString('ru-RU', {
    day: '2-digit', month: '2-digit', year: 'numeric',
    hour: '2-digit', minute: '2-digit'
  });
}

function yn(v) {
  if (v === true || v === 'true' || v === 't' || v === 1) return 'да';
  if (v === false || v === 'false' || v === 'f' || v === 0) return 'нет';
  return v === null || v === undefined || v === '' ? '—' : String(v);
}

function money(v) {
  if (v === null || v === undefined || v === '') return '—';
  return String(v) + ' ₽';
}

const username = user.username ? '@' + String(user.username).replace(/^@/, '') : '—';
const fullName = [user.first_name, user.last_name].filter(Boolean).join(' ') || '—';
const referrer = user.referrer_username
  ? '@' + String(user.referrer_username).replace(/^@/, '')
  : (user.referrer_tg_id || '—');

let restrictions = 'нет';
if (user.restriction_topup || user.restriction_subscription) {
  const parts = [];
  if (user.restriction_topup) parts.push('пополнение');
  if (user.restriction_subscription) parts.push('подписка');
  restrictions = parts.join(', ');
  if (user.restriction_reason) restrictions += ' (' + user.restriction_reason + ')';
}

let keysText = '';
const count = items.length;
if (count === 0) {
  keysText = '❌ Подписки отсутствуют';
} else {
  keysText = '🔑 Подписки (' + count + '):\n';
  items.forEach((item, index) => {
    const k = item.json;
    const trafficLimit = (k.traffic_limit_gb === 0 || k.traffic_limit_gb === '0')
      ? 'безлимит'
      : ((k.traffic_limit_gb ?? '—') + ' ГБ');
    keysText += '\n' + (index + 1) + '. ' + (k.email || '—') + '\n';
    keysText += '   Тариф: ' + (k.server_id || '—') + '\n';
    keysText += '   Статус: ' + (k.status || '—') + ' | Триал: ' + yn(k.is_trial) + '\n';
    keysText += '   Старт: ' + fmtDate(k.start_date) + '\n';
    keysText += '   До: ' + fmtDate(k.end_date || k.expiry_time) + '\n';
    keysText += '   Устройства: ' + (k.device_limit ?? '—') + '\n';
    keysText += '   Трафик: ' + (k.traffic_used_gb ?? 0) + ' / ' + trafficLimit + '\n';
    keysText += '   Автооплата: ' + yn(k.autopay_enabled);
    if (k.autopay_enabled) keysText += ' (за ' + (k.autopay_days_before ?? '—') + ' дн.)';
    keysText += '\n';
    if (k.is_daily_paused) keysText += '   Daily pause: да\n';
    if (k.modem_enabled) keysText += '   Modem: да\n';
  });
}

const lines = [
  '🆔 Telegram ID: ' + (user.tg_id ?? '—'),
  '👤 Username: ' + username,
  '📛 Имя: ' + fullName,
  '📌 Статус: ' + (user.status ?? '—'),
  '🌐 Язык: ' + (user.language ?? '—') + ' | Auth: ' + (user.auth_type ?? '—'),
  '✉️ Email: ' + (user.email || '—') + ' (verified: ' + yn(user.email_verified) + ')',
  '💰 Баланс: ' + money(user.balance),
  '🎯 Триал: ' + yn(user.trial) + ' | Была оплата: ' + yn(user.had_paid) + ' | Первый top-up: ' + yn(user.first_topup),
  '🏷 Промогруппа: ' + (user.promo_group || '—') + ' | Промокодов: ' + (user.used_promocodes ?? 0),
  '🤝 Партнёр: ' + (user.partner_status || '—'),
  '🔗 Реф.код: ' + (user.referral_code || '—') + ' | Реферер: ' + referrer + ' | Рефералов: ' + (user.referrals_count ?? 0),
  '💳 Депозиты: ' + money(user.total_deposits),
  '💳 Последний депозит: ' + money(user.last_deposit_amount) + ' | ' + fmtDate(user.last_deposit_at) + ' | ' + (user.last_deposit_method || '—'),
  '🧾 Последняя операция: ' + (user.last_tx_type || '—') + ' | ' + money(user.last_tx_amount) + ' | ' + fmtDate(user.last_tx_at),
  '🎟 Тикеты: открытых ' + (user.open_tickets ?? 0) + ' / всего ' + (user.tickets_total ?? 0),
  '🚫 Ограничения: ' + restrictions,
  '📊 Lifetime трафик: ' + (user.lifetime_traffic_gb ?? 0) + ' ГБ',
  '📅 Регистрация: ' + fmtDate(user.created_at),
  '🕐 Активность: ' + fmtDate(user.last_activity),
  '🖥 Вход в кабинет: ' + fmtDate(user.cabinet_last_login),
  '🧬 Remnawave UUID: ' + (user.remnawave_uuid || '—'),
  '',
  keysText.trim()
];

return [{
  json: {
    message: lines.join('\n'),
    keys_text: keysText,
    keys_count: count
  }
}];

