={{ (() => {
  const dialog = $('Добавить диалог').item.json;
  const user = $('Получить данные пользователя').item.json;
  const buttons = [
    [{ text: '🔄 Переключить AI', callback_data: 'toggle_ai:' + dialog.id + ':' + dialog.user_id }],
  ];
  if (user.id) {
    buttons.push([{ text: 'Карточка пользователя', url: (($env.CABINET_URL || 'https://cab.example.com').replace(/\/+$/,'')) + '/admin/users/' + user.id }]);
  }
  return JSON.stringify({
    type: 'user_message',
    dialog_id: dialog.id,
    chat_id: dialog.user_id,
    message: $json.message,
    ai_enabled: dialog.ai_status,
    buttons
  });
})() }}

